export function translateText(value: string, language: Language): string {
  if (language === 'en') return value;
  const dictionary = translations[language];
  const leading = value.match(/^\s*/)?.[0] ?? '';
  const trailing = value.match(/\s*$/)?.[0] ?? '';
  const text = value.slice(leading.length, value.length - trailing.length || undefined);
  if (!text) return value;
  const exact = dictionary[text];
  if (exact) return `${leading}${exact}${trailing}`;
  let translated = text;
  for (const [source, target] of Object.entries(dictionary).sort((a, b) => b[0].length - a[0].length)) {
    if (source.endsWith(' ')) {
      const prefix = source.trimEnd();
      if (translated.startsWith(prefix) && (translated.length === prefix.length || /\s/.test(translated[prefix.length]))) {
        translated = `${target}${translated.slice(prefix.length)}`;
      }
      continue;
    }
    if (source.length < 4 && source.toUpperCase() !== source) continue;
    const escaped = source.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const wholePhrase = new RegExp(`(^|[^A-Za-z0-9])${escaped}(?=$|[^A-Za-z0-9])`, 'g');
    translated = translated.replace(wholePhrase, (_match, prefix: string) => `${prefix}${target}`);
  }
  return `${leading}${translated}${trailing}`;
}

function translateNode(node: ReactNode, language: Language): ReactNode {
  if (typeof node === 'string') return translateText(node, language);
  if (Array.isArray(node)) return node.map(child => translateNode(child, language));
  type LocalizedElementProps = { children?: ReactNode; [key: string]: unknown };
  if (!isValidElement<LocalizedElementProps>(node) || (typeof node.type !== 'string' && node.type !== Fragment)) return node;

  const props: Partial<LocalizedElementProps> = {};
  for (const name of ['aria-label', 'alt', 'placeholder', 'title']) {
    const value = node.props[name];
    if (typeof value === 'string') props[name] = translateText(value, language);
  }
  const children = node.props.children;
  if (children === undefined) return cloneElement(node, props);
  if (Array.isArray(children)) {
    return cloneElement(node, props, ...children.map(child => translateNode(child, language)));
  }
  return cloneElement(node, props, translateNode(children, language));
}

export function LocalizedMarkup({ language, children }: { language: Language; children: ReactNode }) {
  return <>{translateNode(children, language)}</>;
}
